    "nav.contact": "Contáctanos",
    "core.eyebrow": "Nuestra Esencia",
    "core.title": "La Base Sobre la Que Se Construye Basma",
    "core.body": "Basma es una agencia tecnológica integral. Transformamos las ideas — de empresas e individuos por igual — en una presencia digital completa: desde el sitio web y la identidad visual, hasta las campañas de marketing y el contenido escrito y visual. No somos solo otro proveedor. Somos un socio técnico que trata tu proyecto como propio, y cuida cada detalle hasta que tu huella se distinga claramente en el mercado.",
    "vision.title": "Visión",
    "vision.body": "Ser el primer destino para los proyectos ambiciosos que quieren construir su presencia digital completa — una agencia digital que es más que un proveedor de servicios; cuando alguien piensa en Basma, piensa en un socio técnico que cubre todo desde la primera idea hasta una presencia digital memorable.",
    "why.title": "Por Qué Basma",
    "why.body": "Basma no es una agencia que entrega un servicio y se va. Somos tu socio técnico completo — desde la primera línea de código de tu sitio, hasta la campaña de marketing que llega a tus clientes, hasta la identidad visual que te hace reconocible de un vistazo. Tratamos cada proyecto como propio, y medimos nuestro éxito por el éxito de los proyectos en los que trabajamos.",
    "model.eyebrow": "Modelo de Negocio",
    "model.title": "Cómo Genera Ingresos Basma",
    "model.subtitle": "Cuatro vías complementarias — sin depender de un solo tipo de proyecto.",
    "model1.title": "Paquetes Mensuales Integrales",
    "model1.desc": "Diseño + desarrollo + marketing + gestión de contenido bajo un contrato continuo, para clientes que quieren una presencia digital permanente.",
    "model2.title": "Proyectos de Ejecución Única",
    "model2.desc": "Sitios web, tiendas o identidades visuales con un alcance definido y una entrega final clara.",
    "model3.title": "Contratos de Mantenimiento y Soporte",
    "model3.desc": "Actualizaciones, alojamiento y seguimiento técnico de proyectos existentes — los hayamos construido o no.",
    "model4.title": "Consultoría Digital",
    "model4.desc": "Sesiones y planes para clientes que quieren construir su equipo interno pero necesitan dirección estratégica primero.",
    "mission.title": "Misión",
    "mission.body": "Reunimos diseño, desarrollo, marketing y contenido bajo un mismo techo, con un equipo que asume la responsabilidad total de cada proyecto — desde la primera idea hasta la ejecución y el soporte posterior al lanzamiento. Nuestro objetivo no es solo entregar un proyecto y seguir adelante; es construir una asociación técnica a largo plazo que crezca junto a nuestro cliente.",
    "services.eyebrow": "Nuestros Servicios",
    "services.title": "Toda la Tecnología, en un Solo Lugar",
    "svc1.title": "Desarrollo Web y de Apps",
    "svc1.desc": "Sitios web, tiendas y paneles de control construidos desde cero, rápidos y adaptables a cualquier dispositivo.",
    "svc2.title": "Marketing Digital y Crecimiento",
    "svc2.desc": "Campañas publicitarias, SEO y gestión de redes sociales para hacer crecer tu base de clientes.",
    "svc3.title": "Identidad Visual",
    "svc3.desc": "Logo, colores y un lenguaje visual cohesivo que hace que tu marca sea reconocible de un vistazo.",
    "svc4.title": "Gestión de Contenido y Plataformas",
    "svc4.desc": "Redacción de contenido, gestión diaria de plataformas y paneles fáciles para que administres tu proyecto tú mismo.",
    "svc5.title": "Edición de Video",
    "svc5.desc": "Edición profesional para anuncios y contenido, desde el corte y la corrección de color hasta la sincronización de sonido.",
    "svc6.title": "Diseño Gráfico",
    "svc6.desc": "Diseños visuales para publicaciones, impresos y campañas publicitarias con un toque profesional consistente.",
    "svc7.title": "Motion Graphics",
    "svc7.desc": "Animaciones y videos explicativos que convierten tus ideas complejas en contenido visual simple y atractivo.",
    "svc8.title": "Redacción de Contenido",
    "svc8.desc": "Contenido escrito que transmite la voz de tu marca con claridad — desde textos web hasta planes de contenido completos.",
    "values.title": "En Qué Se Basa Cada Decisión que Tomamos",
