    "problem.eyebrow": "El Reto",
    "problem.title": "Lo Que Frena a la Mayoría de las Empresas en lo Digital",
    "problem1.title": "Presencia Digital Débil",
    "problem1.desc": "Una presencia que no refleja el tamaño ni el valor real de tu empresa frente a la competencia.",
