    "whybasma.eyebrow": "Por Qué Basma",
    "whybasma.title": "¿Por Qué Elegir Basma Específicamente?",
    "whybasma1.title": "Un Equipo Integral",
    "whybasma1.desc": "Todos tus servicios digitales en un solo lugar, sin coordinar entre varios proveedores.",
    "whybasma2.title": "Soluciones a Medida",
