    "whybasma6.title": "Comunicación Directa",
    "whybasma6.desc": "Sin intermediarios — hablas directamente con el equipo que construye tu proyecto.",
    "process.eyebrow": "Cómo Trabajamos",
    "process.title": "¿Cómo Trabajamos?",
    "process1.title": "Descubrimiento",
    "process1.desc": "Entendemos tu objetivo, tu audiencia y tu necesidad real.",
    "process2.title": "Planificación",
