    "svc.motion.faq4.q": "¿Se pueden combinar tomas de video reales con la animación?",
    "svc.motion.faq4.a": "Sí, podemos combinar tomas reales con elementos de motion graphics dentro del mismo video según la idea del proyecto.",

    "svc.video.who.title": "¿Para quién es este servicio?",
    "svc.video.who.body": "Creadores de contenido y empresas que tienen metraje de video sin editar y necesitan una edición profesional lista para publicar. También es ideal para quienes filman su propio material (con teléfono o cámara) y necesitan convertirlo en contenido final pulido sin aprender software de edición.",
    "svc.video.problem.title": "El problema que resuelve",
    "svc.video.problem.body": "El metraje sin procesar —sin corte, corrección de color o sincronización de audio— no se ve profesional sin importar la calidad de la filmación original. La falta de una sincronización precisa entre audio e imagen, o un formato inadecuado para la plataforma, también reduce el nivel de profesionalismo que percibe el espectador.",
    "svc.video.includes.title": "¿Qué incluye el servicio?",
    "svc.video.inc1": "Corte y organización de tomas",
    "svc.video.inc2": "Corrección de color",
    "svc.video.inc3": "Sincronización y procesamiento de audio",
    "svc.video.inc4": "Añadir efectos y textos cuando se necesite",
    "svc.video.why.title": "¿Por qué edición de video con Basma?",
    "svc.video.why.body": "No nos limitamos a cortar y ordenar las tomas: tratamos el color y el audio con cuidado para lograr un resultado que se vea filmado profesionalmente incluso si el material original era sencillo. Preparamos cada video en el tamaño y formato adecuados para su plataforma (Reels, historias, YouTube) en lugar de una sola versión usada en todas partes.",
    "svc.video.step1.title": "Descubrimiento",
