    "svc.seo.who.title": "¿Para quién es este servicio?",
    "svc.seo.who.body": "Dueños de sitios que quieren mejorar la visibilidad de su sitio en los resultados de búsqueda sin recurrir a soluciones exageradas o poco claras. También es ideal para dueños de sitios nuevos que quieren construir una base técnica sólida para los buscadores desde el lanzamiento, en lugar de corregirla después.",
    "svc.seo.problem.title": "El problema que resuelve",
    "svc.seo.problem.body": "Muchos sitios tienen problemas técnicos simples (velocidad, títulos, descripciones de página) que les impiden posicionarse aunque su contenido sea bueno. Algunos ni siquiera aparecen en los resultados de búsqueda por problemas técnicos de indexación (sitemap, robots, errores de rastreo) que no tienen relación con la calidad del contenido.",
    "svc.seo.includes.title": "¿Qué incluye el servicio?",
    "svc.seo.inc1": "Revisión técnica del sitio (velocidad, títulos, enlaces)",
    "svc.seo.inc2": "Mejora del contenido existente para servir tanto a visitantes como a buscadores",
    "svc.seo.inc3": "Configuración o revisión del sitemap y el archivo robots",
    "svc.seo.inc4": "Seguimiento del rendimiento y recomendaciones periódicas",
    "svc.seo.why.title": "¿Por qué SEO con Basma?",
    "svc.seo.why.body": "Revisamos primero el aspecto técnico (velocidad, indexación, estructura de enlaces) antes de hablar de palabras clave, porque un sitio que Google no puede indexar correctamente no se beneficiará ni del mejor contenido. Revisamos o preparamos el sitemap y el archivo robots para asegurar que los buscadores puedan acceder a todas tus páginas importantes, y hacemos seguimiento del rendimiento con herramientas como Search Console en lugar de basarnos en suposiciones.",
    "svc.seo.step1.title": "Descubrimiento",
    "svc.seo.step1.desc": "Revisamos el estado técnico actual del sitio (velocidad, indexación, títulos, enlaces) e identificamos los problemas reales.",
    "svc.seo.step2.title": "Planificación",
    "svc.seo.step2.desc": "Elaboramos un plan de mejora priorizado, empezando por los problemas de mayor impacto.",
    "svc.seo.step3.title": "Desarrollo",
    "svc.seo.step3.desc": "Implementamos las mejoras técnicas y revisamos o preparamos el contenido para que sirva a visitantes y buscadores a la vez.",
    "svc.seo.step4.title": "Revisión",
    "svc.seo.step4.desc": "Hacemos seguimiento de la visibilidad del sitio con herramientas de medición (como Search Console) para confirmar que la indexación mejora.",
    "svc.seo.step5.title": "Entrega",
    "svc.seo.step5.desc": "Ofrecemos recomendaciones periódicas basadas en los datos reales de rendimiento del sitio.",
