    "svc.seo.faq1.q": "¿La mejora de SEO requiere rediseñar el sitio?",
    "svc.seo.faq1.a": "No necesariamente; los problemas suelen ser técnicos o de contenido y pueden resolverse sin un rediseño completo.",
    "svc.seo.faq2.q": "¿El servicio incluye escribir o editar contenido?",
    "svc.seo.faq2.a": "Sí, revisamos y mejoramos el contenido existente para servir tanto a visitantes como a buscadores, sin relleno de palabras clave.",
    "svc.seo.faq3.q": "¿Los resultados aparecen de inmediato?",
    "svc.seo.faq3.a": "El SEO es un proceso continuo que requiere tiempo y seguimiento; no prometemos resultados instantáneos.",
    "svc.seo.faq4.q": "¿Ofrecen informes periódicos de rendimiento?",
    "svc.seo.faq4.a": "Sí, compartimos informes periódicos que muestran el rendimiento del sitio en las búsquedas y las recomendaciones que se derivan de ello.",

    "svc.dm.who.title": "¿Para quién es este servicio?",
    "svc.dm.who.body": "Empresas que gestionan un presupuesto publicitario y necesitan a alguien que administre sus campañas y analice el rendimiento en lugar de gastar al azar. También es ideal para empresas que probaron anuncios antes sin resultados claros y quieren que alguien reconstruya la estrategia desde cero en lugar de continuar con el mismo enfoque.",
    "svc.dm.problem.title": "El problema que resuelve",
    "svc.dm.problem.body": "El gasto publicitario sin medición y seguimiento continuo suele terminar en canales que no generan un retorno real. Y sin un recorrido claro desde la primera impresión del anuncio hasta la decisión de compra (un funnel), los visitantes llegan al sitio sin convertirse realmente en clientes.",
    "svc.dm.includes.title": "¿Qué incluye el servicio?",
