    "svc.dm.why.title": "¿Por qué marketing digital con Basma?",
    "svc.dm.why.body": "Construimos la estrategia de campaña alrededor de un objetivo comercial claro (leads, ventas, reservas) en lugar de campañas genéricas sin un propósito definido. Diseñamos un recorrido claro desde la primera impresión del anuncio hasta el paso de conversión (un funnel), y analizamos el rendimiento semanalmente para redistribuir el presupuesto hacia lo que realmente funciona, en lugar de mantener un canal de bajo rendimiento.",
    "svc.dm.step1.title": "Descubrimiento",
    "svc.dm.step1.desc": "Revisamos tu negocio y tu público objetivo, y definimos el objetivo central de la campaña (leads, ventas, reservas).",
    "svc.dm.step2.title": "Planificación",
    "svc.dm.step2.desc": "Definimos la estrategia de canales, el presupuesto y el funnel de conversión adecuado para tu objetivo.",
    "svc.dm.step3.title": "Lanzamiento",
    "svc.dm.step3.desc": "Lanzamos las campañas e implementamos las mejoras técnicas del sitio que respaldan la llegada de visitantes.",
    "svc.dm.step4.title": "Revisión",
    "svc.dm.step4.desc": "Analizamos el rendimiento de las campañas de forma continua y ajustamos la segmentación o el presupuesto según los resultados.",
    "svc.dm.step5.title": "Entrega",
