    "svc.smm.who.title": "¿Para quién es este servicio?",
    "svc.smm.who.body": "Dueños de negocios que no tienen tiempo para gestionar sus plataformas con regularidad, o que quieren delegar esta tarea a un equipo especializado. También es ideal para empresas que tienen buen contenido pero lo publican de forma irregular, sin un plan o calendario claro.",
