    "svc.smm.why.body": "Empezamos con un calendario de contenido mensual basado en una estrategia clara, no publicaciones al azar sin un hilo que las conecte. Hacemos seguimiento de comentarios y mensajes dentro del alcance de trabajo acordado para mantener una interacción genuina con tu audiencia, y compartimos un resumen de rendimiento periódico que muestra qué funciona y qué necesita ajustes.",
    "svc.smm.step1.title": "Descubrimiento",
    "svc.smm.step1.desc": "Entendemos tu negocio y tu público objetivo en cada plataforma, y el tono adecuado para tu marca.",
