    "svc.content.who.title": "¿Para quién es este servicio?",
    "svc.content.who.body": "Dueños de sitios y proyectos que necesitan textos profesionales que reflejen la voz de su marca, en lugar de textos genéricos e intercambiables. También es ideal para empresas que producen contenido con regularidad (blog, boletines por correo, publicaciones) y necesitan una voz escrita consistente en todos esos canales.",
    "svc.content.problem.title": "El problema que resuelve",
    "svc.content.problem.body": "Los textos genéricos o traducidos literalmente suelen perder la voz de la marca y parecen no tener una personalidad propia. La falta de una voz escrita consistente en los distintos canales —el sitio, las publicaciones, los mensajes— también hace que la marca parezca varias entidades distintas hablando en su nombre.",
