    "مشروع محدد بنطاق وسعر واضحين من البداية حتى التسليم.":"A defined project with clear scope and pricing from start to delivery.",
    "متابعة دورية واستجابة سريعة لأي مشروع قائم لديك.":"Regular follow-up and fast response for your existing project.",
