    "من نحن":"About Us",
    "قيمنا":"Our Values",
    "رحلتنا":"Our Journey",
    "رؤيتنا":"Our Vision",
    "رسالتنا":"Our Mission",
    "لماذا بصمة؟":"Why Basma?",
    "أن نكون الوجهة الأولى للشركات الناشئة والمشاريع الطموحة التي تريد بناء حضور رقمي كامل، واضح، ومؤثر؛ من أول فكرة إلى بصمة لا تُنسى.":"To be the first choice for startups and ambitious projects seeking a complete, clear, and impactful digital presence—from the first idea to an unforgettable mark.",
    "نجمع التصميم والبرمجة والتسويق والمحتوى تحت سقف واحد، ونتعامل مع كل مشروع بمسؤولية كاملة من الفكرة حتى التنفيذ والدعم بعد الإطلاق.":"We bring design, development, marketing, and content under one roof, taking full responsibility from idea through execution and post-launch support.",
    "لأنك لا تحتاج مزوّد خدمة ينفّذ ويغادر، بل شريكًا يفهم مشروعك ويتابع كل تفاصيله. نقيس نجاحنا بالنتيجة التي يحققها مشروعك، ونبقى معك بعد الإطلاق للتطوير والنمو.":"Because you need more than a provider who delivers and leaves—you need a partner who understands every detail. We measure our success by your results and stay after launch to support growth.",
    "مبادئ واضحة تحكم طريقة عملنا وعلاقتنا مع كل عميل.":"Clear principles guide how we work and how we build every client relationship.",
    "نتعامل مع مشروعك كأنه مشروعنا، ونبني علاقة تستمر بعد التسليم.":"We treat your project as our own and build a relationship that continues beyond delivery.",
    "لا نطلق أي عمل قبل أن يصبح جاهزًا ليمثّلك بأفضل صورة.":"We launch nothing until it is ready to represent you at your best.",
    "خطوات وأسعار ومواعيد واضحة من البداية، بلا مفاجآت.":"Clear steps, pricing, and timelines from the start—without surprises.",
    "التصميم والبرمجة والتسويق تعمل معًا كمنظومة واحدة.":"Design, development, and marketing work together as one system.",
    "الإطلاق ليس النهاية؛ بل بداية القياس والتحسين والنمو.":"Launch is not the end; it is the beginning of measurement, improvement, and growth.",
    "نتعلم ونقيس ونحسّن لنقدّم نتيجة أفضل في كل مرحلة.":"We learn, measure, and improve to deliver better results at every stage.",
    "نمو مدروس، خطوة بخطوة":"Thoughtful Growth, Step by Step",
    "نبني اليوم أساسًا قويًا لوكالة رقمية تتوسع بثقة.":"Today we are building a strong foundation for a digital agency that grows with confidence.",
    "نبحث عن شراكات تصنع قيمة مشتركة":"We Seek Partnerships That Create Shared Value",
    "نبحث عن شركات ومؤسسات تؤمن بأن أفضل النتائج تبدأ بتعاون حقيقي. نقدّم خبرتنا الرقمية، ونبني مع شركائنا فرصًا ومشاريع تنمو فيها القيمة للطرفين.":"We seek companies and institutions that believe the best results begin with genuine collaboration. We contribute our digital expertise and build opportunities that create value for both sides.",
    "باب الشراكات مفتوح":"Partnerships Are Open",
    "نرحب بالتعاون مع الشركات والوكالات ومقدمي الخدمات الذين يؤمنون بأن أفضل النتائج تبدأ من تكامل الخبرات ووضوح الأهداف.":"We welcome collaboration with companies, agencies, and service providers who believe strong results come from complementary expertise and clear goals.",
    "أكثر من طريق لشراكة ناجحة":"More Than One Path to a Successful Partnership",
    "اختر النموذج الأقرب لشركتك، أو اقترح علينا نموذجًا جديدًا.":"Choose the model closest to your company, or propose a new one.",
