    "بصمة شريك تقني متكامل يجمع التصميم والبرمجة والتسويق والمحتوى في فريق واحد، ليبني حضورك الرقمي من الفكرة الأولى إلى النمو المستمر.":"Basma is an integrated technical partner bringing design, development, marketing, and content into one team to build your digital presence from the first idea through continuous growth.",
    "بصمة للحلول الرقمية":"Basma Digital Solutions",
    "تواصل معنا | بصمة للحلول الرقمية":"Contact Us | Basma Digital Solutions",
