    "بصمة.":"a Mark.",
    "أرسل لنا نبذة بسيطة، والباقي نكتشفه معًا.":"Send us a short brief, and we will discover the rest together.",
    "بصمة للحلول الرقمية | من الفكرة إلى الإطلاق":"Basma Digital Solutions | From Idea to Launch",
    "بصمة للحلول الرقمية | تصميم وتطوير مواقع، تسويق رقمي وهوية بصرية":"Basma Digital Solutions | Web Design & Development, Digital Marketing & Brand Identity",
    "أن نكون الشريك الأول لبناء":"To Be the First Partner for Building",
    "حضور رقمي متكامل":"an Integrated Digital Presence",
    "نطمح إلى أن تكون بصمة الوجهة التي تجمع الخبرة التقنية والإبداع والتنفيذ المسؤول من أول فكرة وحتى النمو.":"We aspire for Basma to be the destination combining technical expertise, creativity, and responsible execution from the first idea through growth.",
