    "أكبر.":"Greater Impact.",
    "شريك رقمي يضيف قيمة حقيقية":"A Digital Partner That Adds Real Value",
    "نعمل بوضوح ومرونة، ونصمم كل تعاون حسب أهداف الطرفين.":"We work with clarity and flexibility, shaping every collaboration around both parties' goals.",
    "خبرات متكاملة":"Integrated Expertise",
    "التصميم والبرمجة والتسويق والمحتوى ضمن فريق واحد يفهم الصورة كاملة.":"Design, development, marketing, and content within one team that understands the full picture.",
    "تنفيذ مرن":"Flexible Execution",
    "نكيّف طريقة العمل ونطاق التعاون بما يناسب طبيعة شركتك وفرص السوق.":"We adapt the workflow and scope to your company's needs and market opportunities.",
    "نمو مشترك":"Shared Growth",
    "نبحث عن علاقة طويلة المدى تحقق نتائج قابلة للقياس للطرفين.":"We seek a long-term relationship that creates measurable results for both sides.",
    "أشكال التعاون":"Collaboration Models",
    "أعمالنا | بصمة للحلول الرقمية":"Our Work | Basma Digital Solutions",
    "خدماتنا الرقمية | بصمة للحلول الرقمية":"Our Digital Services | Basma Digital Solutions",
    "من الفكرة والهوية إلى التطوير والتسويق، نبني لك حضورًا رقميًا متكاملًا بدل أن تشتت مشروعك بين أكثر من جهة.":"From idea and identity to development and marketing, we build an integrated digital presence so you do not have to split your project across multiple providers.",
    "تطوير مواقع مخصصة":"Custom Website Development",
    "نصمم ونطوّر مواقع سريعة ومتجاوبة تعكس هوية صاحب المشروع، من المواقع التعريفية ومتعددة اللغات إلى المتاجر والأرشيفات وأنظمة الحسابات وتسجيل الدخول.":"We design and develop fast, responsive websites that reflect your identity, from corporate and multilingual sites to stores, archives, account systems, and login platforms.",
    "تصميم مواقع ووردبريس":"WordPress Website Design",
    "تصميم مواقع ووردبريس وواجهات Figma متعددة اللغات":"Multilingual WordPress Website & Figma Interface Design",
    "نصمم واجهات Figma احترافية ونحوّلها إلى مواقع ووردبريس سريعة ومتجاوبة وسهلة الإدارة، مع دعم العربية والإنجليزية والإسبانية، وتحسين السرعة ومحركات البحث وربط نماذج التواصل والدفع عند الحاجة.":"We design professional Figma interfaces and turn them into fast, responsive, easy-to-manage WordPress websites, supporting Arabic, English, and Spanish, with speed and SEO optimization.",
    "نصمم مواقع ووردبريس احترافية وسهلة الإدارة للشركات والجمعيات والمتاجر والمشاريع الناشئة، مع تصميم متجاوب، تحسين السرعة، تهيئة محركات البحث، وربط نماذج التواصل والدفع عند الحاجة.":"We build professional, easy-to-manage WordPress websites for companies, organizations, stores, and startups, with responsive design, speed optimization, SEO, and contact or payment integrations when needed.",
    "تطوير التطبيقات":"Application Development",
    "نطوّر تطبيقات وأنظمة إدارية متكاملة، من تطبيقات الهواتف إلى لوحات التحكم والأرشفة الرقمية، بواجهات عربية واضحة وتجربة استخدام عملية.":"We develop integrated applications and management systems, from mobile apps to dashboards and digital archives, with clear interfaces and practical user experiences.",
    "حملات إعلانية مدروسة عبر منصات التواصل ومحركات البحث، وتحسين تقني ومحتوى متوافق مع SEO، مع تحليل مستمر للنتائج لتوجيه الميزانية نحو القنوات الأعلى أداءً.":"Strategic ad campaigns across social platforms and search engines, technical and content SEO, and continuous analysis to direct budgets toward the highest-performing channels.",
    "إدارة المحتوى والمنصات":"Content & Platform Management",
    "تخطيط تقويم المحتوى، وكتابة المنشورات ونشرها بانتظام، مع لوحات تحكم مبسطة تمكّن العميل من متابعة مشروعه وإدارته بسهولة وبأقل قدر من التعقيد.":"Content calendar planning, post writing and regular publishing, with simple dashboards that let clients follow and manage their projects easily.",
    "تصميم الجرافيك":"Graphic Design",
    "تصاميم حملات ومنشورات إعلانية لمجالات متنوعة، من الجمعيات والمتاجر إلى العيادات والشركات، بأسلوب بصري يناسب هوية كل عميل ويخدم هدف الحملة.":"Campaign and advertising designs for varied sectors, from organizations and stores to clinics and companies, tailored to each client's identity and campaign goal.",
    "رسوم متحركة وفيديوهات توضيحية تحوّل الأفكار المعقدة إلى محتوى بصري جذاب، واضح، وسهل الفهم.":"Motion graphics and explainer videos that turn complex ideas into engaging, clear, and easy-to-understand visual content.",
