    "تتضمن هذه الصفحة مشاريع ونماذج داخلية وتجريبية طوّرها فريق بصمة لإظهار قدراته في التصميم والتطوير. سيتم إضافة مشاريع العملاء الموثقة بعد الحصول على موافقتهم.":"This page includes internal and demo projects developed by the Basma team to showcase its design and development capabilities. Documented client projects will be added once their approval is obtained.",
