    "عرض دراسة الحالة":"View Case Study",
    "نموذج مشروع داخلي":"Internal project sample",
    "تطوير Front-end":"Front-end Development",
    "بنية متعددة اللغات":"Multilingual Structure",
    "نموذج داخلي لموقع تعريفي بتصميم نظيف وبنية متعددة اللغات.":"An internal sample of a corporate website with a clean design and multilingual structure.",
    "التحدي الشائع في هذا النوع من المشاريع هو تقديم محتوى شخصي أو تعريفي بأكثر من لغة دون أن يفقد الموقع بساطته أو سرعته، مع ضمان تجربة استخدام مريحة على مختلف الأجهزة.":"The common challenge in this type of project is presenting personal or corporate content in more than one language without the site losing its simplicity or speed, while ensuring a comfortable experience across devices.",
    "صمّمنا واجهة نظيفة تعتمد على بنية متعددة اللغات وتصميم متجاوب بالكامل، مع نظام تسجيل دخول بسيط يوضّح كيف يمكن تحويل موقع تعريفي إلى منصة تفاعلية عند الحاجة.":"We designed a clean interface built on a multilingual structure and fully responsive design, with a simple login system showing how a corporate site can become an interactive platform when needed.",
    "منصة محتوى رياضي":"Sports Content Platform",
    "تطوير واجهة":"Interface Development",
    "أرشفة محتوى":"Content Archiving",
    "تجربة مستخدم":"User Experience",
    "بحث وتصنيف":"Search & Categorization",
    "نموذج داخلي لواجهة محتوى رياضي مع أرشفة وتصنيف واضح.":"An internal sample of a sports content interface with clear archiving and categorization.",
    "منصات المحتوى الكبيرة تواجه تحديًا في تنظيم كمية كبيرة من المقالات والمواد بطريقة يسهل على الزائر تصفّحها والوصول لما يبحث عنه بسرعة.":"Large content platforms face the challenge of organizing a large volume of articles and material in a way that lets visitors browse easily and quickly find what they're looking for.",
    "بنينا واجهة محتوى رياضي مع نظام أرشفة وتصنيف واضح، يسمح بعرض المواد الحديثة والقديمة معًا دون تشتيت المستخدم.":"We built a sports content interface with a clear archiving and categorization system, letting recent and older material be shown together without distracting the user.",
    "موقع خدمات رقمية":"Digital Services Website",
    "تصميم واجهة":"Interface Design",
    "تطوير موقع خدمات":"Services Website Development",
    "نموذج داخلي لموقع خدمات يعرض العروض بوضوح مع مسار طلب سهل.":"An internal sample of a services website that presents offerings clearly with an easy request path.",
    "مواقع الخدمات تحتاج إلى عرض واضح لما تقدّمه الشركة مع مسار مختصر وسهل يقود الزائر لطلب الخدمة دون تعقيد.":"Services websites need a clear presentation of what the company offers, with a short, easy path that guides the visitor to request the service without complication.",
    "صمّمنا صفحة خدمات مركّزة تعرض كل خدمة بوضوح مع دعوات لاتخاذ إجراء (CTA) واضحة ومتجاوبة على كل المقاسات.":"We designed a focused services page presenting each service clearly, with clear calls to action (CTAs) that are responsive across every screen size.",
    "نموذج تطبيق":"App sample",
    "تصميم تطبيق":"App Design",
    "واجهات عربية":"Arabic Interfaces",
    "نموذج تصميم لتطبيق مواقيت صلاة بواجهات عربية هادئة وواضحة.":"A design sample of a prayer times app with calm, clear Arabic interfaces.",
    "تطبيقات المواقيت الدينية تحتاج لواجهة عربية واضحة وسهلة القراءة في أي وقت من اليوم، مع تنظيم جيد للتقويم والمعلومات المرتبطة به.":"Religious-timing apps need a clear Arabic interface that's easy to read at any time of day, with well-organized calendar and related information.",
    "صممنا واجهات عربية بصرية هادئة تركّز على وضوح الوقت والتاريخ، مع شاشة تقويم مخصصة لعرض المناسبات المرتبطة بسهولة.":"We designed calm visual Arabic interfaces focused on clear time and date display, with a dedicated calendar screen to easily show related occasions.",
    "نموذج نظام إداري":"Admin system sample",
    "تنظيم بيانات":"Data Organization",
    "نموذج تصميم للوحة تحكم نظام إداري طبي منظمة وواضحة.":"A design sample of a well-organized, clear dashboard for a medical management system.",
    "الأنظمة الطبية الإدارية تتعامل مع كمية بيانات كبيرة (مرضى، مواعيد، سجلات)، والتحدي هو عرضها بلوحة تحكم واضحة دون إرباك المستخدم.":"Medical management systems handle a large amount of data (patients, appointments, records), and the challenge is presenting it in a clear dashboard without overwhelming the user.",
    "صممنا لوحة تحكم (Dashboard) منظمة تعرض البيانات الطبية بشكل مرتب وسهل القراءة، مبنية على مبادئ UI/UX تراعي طبيعة العمل الطبي اليومي.":"We designed an organized dashboard that presents medical data in a tidy, easy-to-read way, built on UI/UX principles that respect the nature of daily medical work.",
