    "أنظمة الأرشفة الذكية تحتاج لتجربة دخول آمنة وبسيطة، ولوحة تحكم تسمح بتنظيم وتصنيف الملفات والمستندات بسهولة.":"Smart archiving systems need a secure, simple login experience, and a dashboard that allows files and documents to be organized and categorized easily.",
    "صممنا شاشة تسجيل دخول واضحة ولوحة تحكم مخصصة لعرض وتنظيم الأرشيف الرقمي، مع تركيز على سهولة الوصول للملفات.":"We designed a clear login screen and a custom dashboard for viewing and organizing the digital archive, with a focus on easy file access.",
