    "نموذج هوية بصرية متكاملة لعيادة طبية تعكس الثقة والاحترافية.":"A complete visual identity sample for a medical clinic that reflects trust and professionalism.",
    "العيادات الطبية تحتاج لهوية بصرية تعكس الثقة والاحترافية، وتُطبَّق بثبات على كل نقاط التواصل مع المريض.":"Medical clinics need a visual identity that reflects trust and professionalism, applied consistently across every touchpoint with the patient.",
    "صممنا هوية بصرية متكاملة تشمل نظام ألوان وخطوط هادئ يوحي بالثقة، مع تطبيقات جاهزة للاستخدام على مختلف مواد العيادة.":"We designed a complete visual identity including a calm color and typography system that conveys trust, with applications ready to use across the clinic's various materials.",
    "هوية علامة أزياء":"Fashion Brand Identity",
    "نموذج هوية بصرية لعلامة أزياء باتجاه بصري مميز.":"A visual identity sample for a fashion brand with a distinctive visual direction.",
    "علامات الأزياء تحتاج هوية بصرية مميزة تعكس شخصية العلامة وتبرز في سوق تنافسي بصريًا.":"Fashion brands need a distinctive visual identity that reflects the brand's personality and stands out in a visually competitive market.",
    "طوّرنا اتجاهًا بصريًا (Visual Direction) واضحًا للعلامة مع تطبيقات متعددة تُبقي الهوية متسقة عبر كل المنتجات والمنصات.":"We developed a clear visual direction for the brand with multiple applications that keep the identity consistent across all products and platforms.",
