    "نموذج هوية بصرية فاخرة لعلامة عطور بإخراج بصري راقٍ.":"A luxury visual identity sample for a perfume brand with an elegant visual presentation.",
    "علامات العطور تعتمد بشكل كبير على الإحساس البصري والفخامة، والتحدي هو ترجمة ذلك الإحساس لشعار وهوية ملموسة.":"Perfume brands rely heavily on visual feel and luxury, and the challenge is translating that feeling into a tangible logo and identity.",
    "صممنا شعارًا وهوية بصرية بإخراج فاخر يعكس طبيعة المنتج، مع تطبيقات متعددة تحافظ على نفس الإحساس البصري.":"We designed a logo and visual identity with a luxurious presentation that reflects the product's nature, with multiple applications preserving the same visual feel.",
