    "الشركات القانونية تحتاج هوية بصرية رسمية توحي بالثقة والمصداقية، وتُطبَّق بدقة على المطبوعات والمستندات الرسمية.":"Law firms need a formal visual identity that conveys trust and credibility, applied precisely across print materials and official documents.",
    "صممنا هوية مؤسسية بأسلوب بصري رسمي ومتّزن، مع تصميم مطبوعات متسقة تعكس جدية الشركة القانونية.":"We designed a corporate identity with a formal, balanced visual style, with consistent print design that reflects the law firm's seriousness.",
