    "الجمعيات الخيرية تحتاج تصاميم تواصل اجتماعي تلامس المشاعر وتوضّح الرسالة بسرعة دون الحاجة لنص طويل.":"Charities need social media designs that touch emotions and convey the message quickly without needing lengthy text.",
    "صممنا مجموعة تصاميم لحملات توعوية وخيرية بأسلوب بصري واضح يخدم رسالة كل حملة على منصات التواصل.":"We designed a set of visuals for awareness and charity campaigns with a clear visual style that serves each campaign's message on social platforms.",
