    "صممنا منشورات وعروض خدمات طبية بأسلوب بصري واضح ومهني يناسب طبيعة المحتوى الطبي على منصات التواصل.":"We designed medical service posts and offers with a clear, professional visual style suited to the nature of medical content on social platforms.",
