    "الشركات الصناعية غالبًا ما يكون محتواها البصري تقنيًا وجافًا، والتحدي هو تقديمه بشكل احترافي وجذاب.":"Industrial companies' visual content is often technical and dry, and the challenge is presenting it in a professional and appealing way.",
    "صممنا محتوى بصري مؤسسي يقدّم طبيعة العمل الصناعي بأسلوب احترافي يدعم هوية الشركة في حملاتها.":"We designed corporate visual content that presents the nature of industrial work in a professional style supporting the company's identity across its campaigns.",
