    "تحويل فكرة أو معلومة معقدة إلى محتوى مرئي متحرك يشرحها بوضوح خلال ثوانٍ معدودة يتطلب سرد بصري مدروس.":"Turning a complex idea or piece of information into moving visual content that explains it clearly within seconds requires thoughtful visual storytelling.",
    "نعمل على تصميم رسوم متحركة ومقاطع موشن جرافيك تبسّط الفكرة بصريًا، بدءًا من الإعداد وحتى المونتاج النهائي.":"We design animations and motion graphics clips that simplify the idea visually, from preparation through to final editing.",
