    "إدارة منصات متعددة بانتظام يحتاج لتخطيط محتوى واضح ومتابعة مستمرة حتى لا يتوقف الحضور الرقمي أو يفقد اتساقه.":"Regularly managing multiple platforms needs clear content planning and continuous follow-up so the digital presence doesn't stall or lose consistency.",
    "نبني تقويم محتوى منظم وننشر بانتظام عبر المنصات المطلوبة، مع متابعة الأداء لتحسين النتائج بمرور الوقت.":"We build an organized content calendar and publish regularly across the required platforms, tracking performance to improve results over time.",
