    "نموذج داخلي لإدارة حملات تسويق رقمي مبنية على التحليلات.":"An internal sample for managing digital marketing campaigns based on analytics.",
    "الحملات التسويقية الرقمية تحتاج لقياس مستمر لتوجيه الميزانية نحو القنوات الأعلى أداءً بدل الإنفاق العشوائي.":"Digital marketing campaigns need continuous measurement to direct the budget toward the highest-performing channels instead of spending randomly.",
    "ندير الحملات بالاعتماد على تحليلات الأداء المستمرة، ونعدّل الاستهداف والمحتوى بناءً على النتائج الفعلية.":"We manage campaigns based on continuous performance analytics, adjusting targeting and content based on actual results.",
