    "نموذج عمل في كتابة محتوى يحمل صوت العلامة بوضوح.":"A work sample in content writing that clearly carries the brand's voice.",
    "المحتوى المكتوب يحتاج صوتًا واضحًا ومتسقًا يعكس هوية العلامة عبر كل القنوات، بدل نصوص عامة تتشابه مع الجميع.":"Written content needs a clear, consistent voice that reflects the brand's identity across every channel, instead of generic text that sounds like everyone else's.",
    "نخطط للمحتوى التحريري ونكتب نصوصًا تحمل صوت العلامة بوضوح، بدءًا من فكرة المقال وحتى الصياغة النهائية.":"We plan editorial content and write copy that clearly carries the brand's voice, from the article idea through to the final wording.",
