    "لأن كل تفصيل يُبنى لهدف واضح":"Because Every Detail Is Built With a Clear Purpose",
    "مبني وفق احتياجك":"Built Around Your Needs",
    "كل مشروع يُبنى وفق احتياجات صاحبه الفعلية، وليس نسخة معدّة سلفًا.":"Every project is built around its owner's real needs, not a pre-made copy.",
    "بدون قوالب جاهزة":"No Ready-Made Templates",
    "لا نستخدم قوالب جاهزة؛ كل واجهة تُصمَّم من الصفر لتناسب المشروع.":"We don't use ready-made templates; every interface is designed from scratch to fit the project.",
