    "كل المواقع التي نطورها متجاوبة بالكامل على مختلف مقاسات الشاشات.":"Every website we develop is fully responsive across all screen sizes.",
    "هل يمكن ربط الموقع بنظام تسجيل دخول أو حسابات؟":"Can the website be connected to a login or account system?",
    "نعم، نضيف أنظمة تسجيل دخول وحسابات مستخدمين عند الحاجة لطبيعة المشروع.":"Yes, we add login and user account systems when the nature of the project requires it.",
