    "تنفيذ حلول رقمية لعملائكم تحت مظلة تعاون واضحة واحترافية.":"Ejecución de soluciones digitales para tus clientes mediante una colaboración clara y profesional.",
    "تطوير حملات أو منتجات رقمية تجمع موارد وخبرات الطرفين.":"Desarrollo de campañas o productos digitales que combinan los recursos y la experiencia de ambas partes.",
    "تبادل الفرص والعملاء عندما يحتاج أحد الطرفين خبرة يقدّمها الآخر.":"Intercambio de oportunidades y clientes cuando una parte necesita la experiencia de la otra.",
    "أرسلوا نبذة عن شركتكم وما تتوقعونه من الشراكة، وسنعود إليكم خلال يوم عمل لترتيب جلسة تعارف.":"Envíanos una breve presentación de tu empresa y tus expectativas. Responderemos en un día hábil para organizar una reunión inicial.",
