    "تتضمن هذه الصفحة مشاريع ونماذج داخلية وتجريبية طوّرها فريق بصمة لإظهار قدراته في التصميم والتطوير. سيتم إضافة مشاريع العملاء الموثقة بعد الحصول على موافقتهم.":"Esta página incluye proyectos internos y de demostración desarrollados por el equipo de Basma para mostrar sus capacidades de diseño y desarrollo. Los proyectos de clientes documentados se añadirán una vez obtenida su aprobación.",
