    "نموذج داخلي لموقع تعريفي بتصميم نظيف وبنية متعددة اللغات.":"Una muestra interna de un sitio corporativo con diseño limpio y estructura multilingüe.",
    "التحدي الشائع في هذا النوع من المشاريع هو تقديم محتوى شخصي أو تعريفي بأكثر من لغة دون أن يفقد الموقع بساطته أو سرعته، مع ضمان تجربة استخدام مريحة على مختلف الأجهزة.":"El reto habitual en este tipo de proyectos es presentar contenido personal o corporativo en más de un idioma sin que el sitio pierda simplicidad o velocidad, garantizando una experiencia cómoda en todos los dispositivos.",
    "صمّمنا واجهة نظيفة تعتمد على بنية متعددة اللغات وتصميم متجاوب بالكامل، مع نظام تسجيل دخول بسيط يوضّح كيف يمكن تحويل موقع تعريفي إلى منصة تفاعلية عند الحاجة.":"Diseñamos una interfaz limpia con estructura multilingüe y diseño totalmente adaptable, con un sistema de inicio de sesión simple que muestra cómo un sitio corporativo puede convertirse en una plataforma interactiva cuando se necesita.",
    "منصة محتوى رياضي":"Plataforma de Contenido Deportivo",
