    "نموذج داخلي لموقع خدمات يعرض العروض بوضوح مع مسار طلب سهل.":"Una muestra interna de un sitio de servicios que presenta las ofertas con claridad y un camino de solicitud sencillo.",
    "مواقع الخدمات تحتاج إلى عرض واضح لما تقدّمه الشركة مع مسار مختصر وسهل يقود الزائر لطلب الخدمة دون تعقيد.":"Los sitios de servicios necesitan presentar con claridad lo que ofrece la empresa, con un camino corto y sencillo que guíe al visitante a solicitar el servicio sin complicaciones.",
    "صمّمنا صفحة خدمات مركّزة تعرض كل خدمة بوضوح مع دعوات لاتخاذ إجراء (CTA) واضحة ومتجاوبة على كل المقاسات.":"Diseñamos una página de servicios enfocada que presenta cada servicio con claridad, con llamadas a la acción (CTA) claras y adaptables a todos los tamaños de pantalla.",
    "نموذج تطبيق":"Muestra de aplicación",
