    "نموذج تصميم لتطبيق مواقيت صلاة بواجهات عربية هادئة وواضحة.":"Una muestra de diseño de una app de horarios de oración con interfaces en árabe claras y serenas.",
    "تطبيقات المواقيت الدينية تحتاج لواجهة عربية واضحة وسهلة القراءة في أي وقت من اليوم، مع تنظيم جيد للتقويم والمعلومات المرتبطة به.":"Las aplicaciones de horarios religiosos necesitan una interfaz en árabe clara y fácil de leer a cualquier hora del día, con un calendario e información relacionada bien organizados.",
    "صممنا واجهات عربية بصرية هادئة تركّز على وضوح الوقت والتاريخ، مع شاشة تقويم مخصصة لعرض المناسبات المرتبطة بسهولة.":"Diseñamos interfaces visuales en árabe serenas centradas en mostrar la hora y la fecha con claridad, con una pantalla de calendario dedicada para mostrar fácilmente las fechas relacionadas.",
    "نموذج نظام إداري":"Muestra de sistema administrativo",
    "تنظيم بيانات":"Organización de Datos",
    "نموذج تصميم للوحة تحكم نظام إداري طبي منظمة وواضحة.":"Una muestra de diseño de un panel de control organizado y claro para un sistema de gestión médica.",
    "الأنظمة الطبية الإدارية تتعامل مع كمية بيانات كبيرة (مرضى، مواعيد، سجلات)، والتحدي هو عرضها بلوحة تحكم واضحة دون إرباك المستخدم.":"Los sistemas de gestión médica manejan grandes cantidades de datos (pacientes, citas, historiales), y el reto es presentarlos en un panel claro sin abrumar al usuario.",
    "صممنا لوحة تحكم (Dashboard) منظمة تعرض البيانات الطبية بشكل مرتب وسهل القراءة، مبنية على مبادئ UI/UX تراعي طبيعة العمل الطبي اليومي.":"Diseñamos un panel de control organizado que presenta los datos médicos de forma ordenada y fácil de leer, basado en principios de UI/UX que respetan la naturaleza del trabajo médico diario.",
