    "نموذج منتج رقمي لنظام أرشفة ذكي بتسجيل دخول ولوحة تحكم.":"Una muestra de producto digital de un sistema de archivo inteligente con inicio de sesión y panel de control.",
    "أنظمة الأرشفة الذكية تحتاج لتجربة دخول آمنة وبسيطة، ولوحة تحكم تسمح بتنظيم وتصنيف الملفات والمستندات بسهولة.":"Los sistemas de archivo inteligente necesitan una experiencia de inicio de sesión segura y sencilla, y un panel que permita organizar y clasificar archivos y documentos con facilidad.",
    "صممنا شاشة تسجيل دخول واضحة ولوحة تحكم مخصصة لعرض وتنظيم الأرشيف الرقمي، مع تركيز على سهولة الوصول للملفات.":"Diseñamos una pantalla de inicio de sesión clara y un panel personalizado para visualizar y organizar el archivo digital, centrado en el fácil acceso a los archivos.",
    "هوية عيادة طبية":"Identidad de Clínica Médica",
