    "نموذج هوية بصرية متكاملة لعيادة طبية تعكس الثقة والاحترافية.":"Una muestra de identidad visual completa para una clínica médica que refleja confianza y profesionalismo.",
    "العيادات الطبية تحتاج لهوية بصرية تعكس الثقة والاحترافية، وتُطبَّق بثبات على كل نقاط التواصل مع المريض.":"Las clínicas médicas necesitan una identidad visual que refleje confianza y profesionalismo, aplicada de forma consistente en cada punto de contacto con el paciente.",
    "صممنا هوية بصرية متكاملة تشمل نظام ألوان وخطوط هادئ يوحي بالثقة، مع تطبيقات جاهزة للاستخدام على مختلف مواد العيادة.":"Diseñamos una identidad visual completa que incluye un sistema de colores y tipografía sereno que transmite confianza, con aplicaciones listas para usar en los distintos materiales de la clínica.",
    "هوية علامة أزياء":"Identidad de Marca de Moda",
    "نموذج هوية بصرية لعلامة أزياء باتجاه بصري مميز.":"Una muestra de identidad visual para una marca de moda con una dirección visual distintiva.",
    "علامات الأزياء تحتاج هوية بصرية مميزة تعكس شخصية العلامة وتبرز في سوق تنافسي بصريًا.":"Las marcas de moda necesitan una identidad visual distintiva que refleje la personalidad de la marca y destaque en un mercado visualmente competitivo.",
    "طوّرنا اتجاهًا بصريًا (Visual Direction) واضحًا للعلامة مع تطبيقات متعددة تُبقي الهوية متسقة عبر كل المنتجات والمنصات.":"Desarrollamos una dirección visual clara para la marca con múltiples aplicaciones que mantienen la identidad consistente en todos los productos y plataformas.",
    "هوية علامة عطور":"Identidad de Marca de Perfumes",
