    "نموذج هوية بصرية فاخرة لعلامة عطور بإخراج بصري راقٍ.":"Una muestra de identidad visual de lujo para una marca de perfumes con una presentación visual elegante.",
    "علامات العطور تعتمد بشكل كبير على الإحساس البصري والفخامة، والتحدي هو ترجمة ذلك الإحساس لشعار وهوية ملموسة.":"Las marcas de perfumes dependen en gran medida de la sensación visual y el lujo, y el reto es traducir esa sensación en un logotipo e identidad tangibles.",
    "صممنا شعارًا وهوية بصرية بإخراج فاخر يعكس طبيعة المنتج، مع تطبيقات متعددة تحافظ على نفس الإحساس البصري.":"Diseñamos un logotipo e identidad visual con una presentación lujosa que refleja la naturaleza del producto, con múltiples aplicaciones que mantienen la misma sensación visual.",
