    "نموذج هوية مؤسسية رسمية لشركة قانونية.":"Una muestra de identidad corporativa formal para una firma legal.",
    "الشركات القانونية تحتاج هوية بصرية رسمية توحي بالثقة والمصداقية، وتُطبَّق بدقة على المطبوعات والمستندات الرسمية.":"Las firmas legales necesitan una identidad visual formal que transmita confianza y credibilidad, aplicada con precisión en materiales impresos y documentos oficiales.",
    "صممنا هوية مؤسسية بأسلوب بصري رسمي ومتّزن، مع تصميم مطبوعات متسقة تعكس جدية الشركة القانونية.":"Diseñamos una identidad corporativa con un estilo visual formal y equilibrado, con un diseño de impresos coherente que refleja la seriedad de la firma legal.",
