    "نماذج تصميم لحملات توعوية وخيرية على منصات التواصل.":"Muestras de diseño para campañas de concienciación y benéficas en redes sociales.",
    "الجمعيات الخيرية تحتاج تصاميم تواصل اجتماعي تلامس المشاعر وتوضّح الرسالة بسرعة دون الحاجة لنص طويل.":"Las organizaciones benéficas necesitan diseños para redes sociales que conecten emocionalmente y transmitan el mensaje rápidamente sin necesidad de mucho texto.",
    "صممنا مجموعة تصاميم لحملات توعوية وخيرية بأسلوب بصري واضح يخدم رسالة كل حملة على منصات التواصل.":"Diseñamos un conjunto de piezas visuales para campañas de concienciación y benéficas con un estilo visual claro que sirve al mensaje de cada campaña en redes sociales.",
